"""Driver table QA and data dictionary. usage: 22_driver_qa.py PROCESSED RAW OUT_DIR"""
import sys, warnings
import numpy as np, pandas as pd, geopandas as gpd
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
warnings.filterwarnings('ignore')
p, raw, od = sys.argv[1:4]
R=pd.read_csv(f'{p}/field_drivers.csv',index_col=0); G=gpd.read_file(f'{p}/field_drivers.gpkg'); L=gpd.read_file(f'{raw}/nhd/flowlines.gpkg')
can=L[L.ftype==336]; riv=L[L.gnis_name.fillna('').str.contains('Colorado River')]; G=G.set_index('field_id'); named=can[can.gnis_name.fillna('').str.contains('Canal')]; print('named canal segments',len(named))
R['dist_named_canal_m']=G.geometry.distance(named.geometry.union_all()); R.to_csv(f'{p}/field_drivers.csv')
SURF,INK2,GR='#fcfcfb','#52514e','#e4e3df'
fig,ax=plt.subplots(figsize=(7.5,9.5),facecolor=SURF); ax.set_facecolor(SURF); G.plot(ax=ax,color='#e4e3df',edgecolor='#fcfcfb',linewidth=.2); can.plot(ax=ax,color='#2a78d6',linewidth=.7); riv.plot(ax=ax,color='#eb6834',linewidth=1.5); ax.set_xlim(G.total_bounds[0]-1500,G.total_bounds[2]+1500); ax.set_ylim(G.total_bounds[1]-1500,G.total_bounds[3]+1500); ax.set_axis_off()
ax.plot([],[],color='#2a78d6',label='NHD canal or ditch'); ax.plot([],[],color='#eb6834',label='Colorado River (NHD)'); ax.legend(frameon=False,loc='lower right'); ax.set_title('NHD water features over Palo Verde fields',loc='left',fontsize=14); fig.tight_layout(); fig.savefig(f'{od}/fig_driver_water_qa.png',dpi=130)
num=R.select_dtypes('number').drop(columns=[c for c in ['soil_coverage','x_km','y_km'] if c in R]); c=num.corr(method='spearman').abs(); pairs=[(a,b,round(c.loc[a,b],2)) for i,a in enumerate(c.columns) for b in c.columns[i+1:] if c.loc[a,b]>=.8]; print('|Spearman| >= 0.8:',sorted(pairs,key=lambda x:-x[2]))
print('fields within 30 m of a canal or ditch: %.1f%%'%(100*(R.dist_canal_m<=30).mean()),'| dist_named_canal_m quartiles',R.dist_named_canal_m.quantile([.25,.5,.75]).round(0).tolist())
for x in ['soil_ec','soil_ksat','soil_claytotal','elev_rel_m']: print(x,'quartiles',R[x].quantile([.05,.25,.5,.75,.95]).round(2).tolist())
D=[('soil_claytotal','Clay, 0-30 cm','%','USDA SSURGO'),('soil_sandtotal','Sand, 0-30 cm','%','USDA SSURGO'),('soil_om','Organic matter, 0-30 cm','%','USDA SSURGO'),('soil_ec','Electrical conductivity (salinity), 0-30 cm','dS/m','USDA SSURGO'),('soil_sar','Sodium adsorption ratio, 0-30 cm','ratio','USDA SSURGO'),('soil_ksat','Saturated hydraulic conductivity, 0-30 cm','um/s','USDA SSURGO'),('soil_awc','Available water capacity, 0-30 cm','cm/cm','USDA SSURGO'),('soil_aws050wta','Available water storage, 0-50 cm','cm','USDA SSURGO muaggatt'),('soil_aws0150wta','Available water storage, 0-150 cm','cm','USDA SSURGO muaggatt'),('soil_icc_num','Irrigated capability class','1-8, lower is better','USDA SSURGO muaggatt'),('soil_drclassdcd','Drainage class, dominant condition','category','USDA SSURGO muaggatt'),('soil_hydgrpdcd','Hydrologic soil group','category','USDA SSURGO muaggatt'),('soil_flodfreqdcd','Flooding frequency','category','USDA SSURGO muaggatt'),('dist_canal_m','Distance to nearest NHD canal or ditch','m','USGS NHD'),('dist_named_canal_m','Distance to nearest NHD feature named Canal','m','USGS NHD'),('dist_named_drain_m','Distance to nearest NHD feature named Drain','m','USGS NHD'),('dist_river_m','Distance to the Colorado River','m','USGS NHD'),('area_ac','Field area','acres','DWR 2021 polygon'),('perimeter_m','Field perimeter','m','DWR 2021 polygon'),('compactness_pp','Polsby-Popper compactness (1 = circle)','ratio','DWR 2021 polygon'),('rectangularity','Area over minimum rotated rectangle','ratio','DWR 2021 polygon'),('elev_m','Mean elevation','m','USGS 3DEP 10 m'),('elev_sd_m','Within-field elevation SD','m','USGS 3DEP 10 m'),('slope_deg','Mean slope','degrees','USGS 3DEP 10 m'),('elev_rel_m','Elevation relative to valley plane','m','USGS 3DEP 10 m'),('x_km','Centroid easting, UTM 11N','km','derived'),('y_km','Centroid northing, UTM 11N','km','derived'),('dwr_class (separate table)','DWR class per field and water year, for prior crop','category','field_dwr_class_by_year.csv.gz')]
pd.DataFrame(D,columns=['variable','description','unit','source']).to_csv(f'{p}/field_drivers_dictionary.csv',index=False); print('dictionary rows',len(D))
